MOD = 1_000_000_007
BASE = 131


def build(s):
    h = [0] * (len(s) + 1)
    pw = [1] * (len(s) + 1)
    for i, ch in enumerate(s):
        h[i + 1] = (h[i] * BASE + ord(ch)) % MOD
        pw[i + 1] = pw[i] * BASE % MOD
    return h, pw


def window(h, pw, a, length):
    return (h[a + length] - h[a] * pw[length]) % MOD


def same(h, pw, a, b, length):
    return window(h, pw, a, length) == window(h, pw, b, length)

