static long[][] build(String s) {
    int n = s.length();
    long[] h = new long[n + 1], pw = new long[n + 1];
    pw[0] = 1;
    for (int i = 0; i < n; i++) {
        h[i + 1] = (h[i] * BASE + s.charAt(i)) % MOD;
        pw[i + 1] = pw[i] * BASE % MOD;
    }
    return new long[][] {h, pw};
}

static long window(long[] h, long[] pw, int a, int len) {
    return ((h[a + len] - h[a] * pw[len] % MOD) % MOD + MOD) % MOD;
}

static boolean same(long[] h, long[] pw, int a, int b, int len) {
    return window(h, pw, a, len) == window(h, pw, b, len);
}

