def count_occurrences(text, pat):
    n, m = len(text), len(pat)
    if m == 0 or m > n:
        return 0
    top = 1
    for _ in range(m - 1):
        top = top * BASE % MOD
    hp = ht = 0
    for i in range(m):
        hp = (hp * BASE + ord(pat[i])) % MOD
        ht = (ht * BASE + ord(text[i])) % MOD
    count = 0
    for i in range(n - m + 1):
        if ht == hp and text[i:i + m] == pat:
            count += 1
        if i + m < n:
            ht = (ht - ord(text[i]) * top) % MOD
            ht = (ht * BASE + ord(text[i + m])) % MOD
    return count

