static int countOccurrences(String text, String pat) {
    int n = text.length(), m = pat.length();
    if (m == 0 || m > n) return 0;
    long top = 1;
    for (int k = 0; k < m - 1; k++) top = top * BASE % MOD;
    long hp = 0, ht = 0;
    for (int i = 0; i < m; i++) {
        hp = (hp * BASE + pat.charAt(i)) % MOD;
        ht = (ht * BASE + text.charAt(i)) % MOD;
    }
    int count = 0;
    for (int i = 0; i + m <= n; i++) {
        if (ht == hp && text.startsWith(pat, i)) count++;
        if (i + m < n) {
            ht = (ht - text.charAt(i) * top % MOD + MOD) % MOD;
            ht = (ht * BASE + text.charAt(i + m)) % MOD;
        }
    }
    return count;
}

